<?php
// Run manually after deployment: php tools/submit-indexnow.php YOUR_INDEXNOW_KEY
$key=$argv[1]??''; if(!$key){fwrite(STDERR,"Missing IndexNow key.\n"); exit(1);} $urls=[]; foreach(glob(__DIR__.'/../sitemaps/services-*.xml') as $f){$x=simplexml_load_file($f); foreach($x->url as $u){$urls[]=(string)$u->loc;}} foreach(array_chunk($urls,10000) as $batch){$payload=json_encode(['host'=>'justsmartchoice.com','key'=>$key,'keyLocation'=>'https://justsmartchoice.com/'.$key.'.txt','urlList'=>$batch]); $ch=curl_init('https://api.indexnow.org/indexnow'); curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json; charset=utf-8'],CURLOPT_POSTFIELDS=>$payload,CURLOPT_RETURNTRANSFER=>true]); $response=curl_exec($ch); echo curl_getinfo($ch,CURLINFO_HTTP_CODE)." ".$response."\n"; curl_close($ch);}
